@contextmanager
def trace_calls(logger: CallTraceLogger, max_typed_dict_size: int,
    code_filter: Optional[CodeFilter]=None, sample_rate: Optional[int]=None
    ) ->Iterator[None]:
    tracer = CallTracer(logger, max_typed_dict_size, code_filter, sample_rate)
    old_profile = sys.getprofile()
    sys.setprofile(tracer)
    try:
        yield
    finally:
        sys.setprofile(old_profile)
        logger.flush()
